INSERT INTO parks (name, lat, lon, region) SELECT 'Motiongate', 24.9205, 55.0040, 'United Arab Emirates' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Motiongate');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Capitol Bullet Train', 'Motiongate', 'Steel', 'MACK Rides', 'MACK Launch', NULL, NULL, 1870.0, 2, NULL, 2017, '2017-10-20', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Capitol Bullet Train' AND park = 'Motiongate');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Capitol Bullet Train' AND c.park = 'Motiongate' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
